package org.brightstats.stats;
import java.util.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.*;import com.google.gson.*;
/** Representation identities with explicit dimensions, labels and canonical JSON keys. */
public final class AnalysisIdentity {
 private AnalysisIdentity(){}
 public static String data(double[][] data,List<String> names){try{MessageDigest digest=MessageDigest.getInstance("SHA-256");digest.update("brightstats-analysis-data-v1".getBytes(StandardCharsets.UTF_8));integer(digest,data.length);integer(digest,names.size());for(String name:names){byte[] bytes=name.getBytes(StandardCharsets.UTF_8);integer(digest,bytes.length);digest.update(bytes);}for(var row:data){if(row.length!=names.size())throw new IllegalArgumentException("Data identity dimensions differ from names.");for(double x:row)digest.update(ByteBuffer.allocate(8).putLong(Double.doubleToLongBits(x)).array());}return HexFormat.of().formatHex(digest.digest());}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
 public static String model(Object model){return json(new GsonBuilder().serializeNulls().create().toJsonTree(model));}
 public static String json(JsonElement value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonicalText(value).getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
 static String canonicalText(JsonElement value){if(value.isJsonObject()){List<String> entries=new ArrayList<>();for(String key:new TreeSet<>(value.getAsJsonObject().keySet()))entries.add(new JsonPrimitive(key).toString()+":"+canonicalText(value.getAsJsonObject().get(key)));return "{"+String.join(",",entries)+"}";}if(value.isJsonArray()){List<String> entries=new ArrayList<>();value.getAsJsonArray().forEach(v->entries.add(canonicalText(v)));return "["+String.join(",",entries)+"]";}if(value.isJsonPrimitive()&&value.getAsJsonPrimitive().isNumber()){double number=value.getAsDouble();if(Double.isNaN(number))return "null";if(Double.isInfinite(number))return new JsonPrimitive(number>0?"Infinity":"-Infinity").toString();return value.getAsBigDecimal().stripTrailingZeros().toPlainString();}return value.toString();}
 private static void integer(MessageDigest digest,int value){digest.update(ByteBuffer.allocate(4).putInt(value).array());}
}
